def contains_cyclic_rotation(a: str, b: str) -> bool:
    """
    Check if string a contains any cyclic rotation of string b.
    A cyclic rotation of string b is obtained by rotating its characters.
    For example, cyclic rotations of "abc" are "abc", "bca", "cab".
    """
    if not b:
        return True  # Empty string is a rotation of itself
    if len(a) < len(b):
        return False

    # Concatenate b with itself to form all possible rotations
    # e.g., b = "abc" -> b+b = "abcabc", rotations are substrings of length len(b)
    double_b = b + b

    # Check if any rotation (substring of double_b of length len(b)) is a substring of a
    return any(
        double_b[i:i+len(b)] in a
        for i in range(len(b))
    )

