def total(n: int) -> int:
    """Sum squares of every 3rd number, cubes of every 4th, otherwise add the number itself."""
    return reduce(
        lambda acc, x: acc + (x**2 if x % 3 == 0 else x**3 if x % 4 == 0 else x),
        range(1, n + 1),
        0
    )

