def remove_integer_part(number):
    """
    Return the fractional part of a number, removing its integer part.
    Works with int, float, Decimal, and complex (returns fractional part of real part).

    Examples:
        >>> remove_integer_part(12.34)
        0.34
        >>> remove_integer_part(-5.67)
        -0.67
        >>> remove_integer_part(3)
        0.0
    """
    import math
    if isinstance(number, complex):
        # For complex numbers, only handle the real part
        number = number.real
    if isinstance(number, (int, float)):
        return number - math.trunc(number)
    try:
        # Try to convert to float if possible
        return float(number) - math.trunc(float(number))
    except Exception as e:
        raise TypeError(f"Unsupported type: {type(number)}") from e


# Example usage
if __name__ == "__main__":
    nums = [12.34, -5.67, 3, 0.0, 123]
    for n in nums:
        print(f"{n} -> {remove_integer_part(n)}")
