def decode(s: str) -> str:
    def rotate_right(triple: str) -> str:
        return triple[-1] + triple[:-1]

    return "".join(
        rotate_right(s[i : i + 3]) if len(s[i : i + 3]) == 3 else s[i : i + 3]
        for i in range(0, len(s), 3)
    )
