def is_right_triangle(a, b, c):
    """
    Checks whether three numbers a, b, and c can be the side lengths of a right‑angled triangle.
    Returns True if any permutation satisfies the Pythagorean theorem, otherwise False.
    """
    return (
        a * a + b * b == c * c or
        a * a + c * c == b * b or
        b * b + c * c == a * a
    )

