def count_substring_occurrences(text: str, substring: str) -> int:
    """
    Counts occurrences of substring in string by iterating through each starting
    position and checking if the remaining string starts with the substring.
    """
    if not substring:
        return 0

    return sum(
        1
        for i in range(len(text) - len(substring) + 1)
        if text[i:].startswith(substring)
    )
